function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[0-9#]+$/.test(s)) return 's may contain only digits and #.';
  let j = s.length - 1;
  while (j >= 0) {
    if (s[j] === '#') {
      const code = j >= 2 ? s.substring(j - 2, j) : '';
      if (!/^[0-9]{2}$/.test(code) || Number(code) < 10 || Number(code) > 26) return 'Each # must follow a two-digit code from 10 to 26.';
      j -= 3;
    } else {
      if (s[j] === '0') return 'A single digit code must be 1 to 9.';
      j -= 1;
    }
  }
  return null;
}

