function freqAlphabets(s) {
  const letters = [];
  let i = 0;

  while (i < s.length) {
    let code;
    if (i + 2 < s.length && s[i + 2] === '#') {
      code = Number(s.slice(i, i + 2));
      i += 3;
    } else {
      code = Number(s[i]);
      i += 1;
    }
    letters.push(String.fromCharCode(96 + code));
  }
  return letters.join('');
}

