function generate(rand, size) {
  const target = size === 'large' ? 960 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 8);
  const longChance = [0, 0.3, 0.6, 1][Math.floor(rand() * 4)];
  let s = '';
  while (s.length < target) {
    const long = s.length + 3 <= target && rand() < longChance;
    s += long ? String(10 + Math.floor(rand() * 17)) + '#' : String(1 + Math.floor(rand() * 9));
  }
  return [s];
}
